+export function evaluateTrackedEventMidiAtWhole(ev: TrackedVoiceEvent, timeWhole: number): number {
+  const dur = Math.max(0.0001, ev.durationWhole);
+  const progress = Math.max(0, Math.min(1, (timeWhole - ev.startWhole) / dur));
+  let pitchOffset = 0;
+  if (ev.pitchBend && ev.pitchBend.length > 0 && ev.pitchBend[0]) {
+    pitchOffset += ev.pitchBend[0].depthSemitones * Math.pow(progress, ev.pitchBend[0].curve || 1);
+  }
+  if (ev.vibrato && ev.vibrato.depthSemitones > 0 && timeWhole >= ev.startWhole && timeWhole <= ev.startWhole + dur) {
+    const elapsedSec = (timeWhole - ev.startWhole) * 2.0;
+    pitchOffset += Math.sin(elapsedSec * ev.vibrato.rateHz * Math.PI * 2) * ev.vibrato.depthSemitones * 0.35;
+  }
+  return ev.midi + pitchOffset;
+}
+
